CAT = "ea1Income"; SEG = "INC"
# Income and assets (SEE Part 1 domain 2). Tax year 2025 unless stated. Computed keys asserted.

# Form 8606 pro rata: basis 12,000; distribution 10,000; year-end value 50,000.
_nontax = 10000 * 12000 // (50000 + 10000); assert _nontax == 2000
# Social Security: single, other income 28,000, tax-exempt interest 1,000, benefits 12,000.
_prov = 28000 + 1000 + 12000 // 2; assert _prov == 35000
_ss = min(int(0.85 * 12000), int(0.85 * (_prov - 34000)) + min(4500, 12000 // 2)); assert _ss == 5350
# SE tax on 40,000 net profit.
_se = round(40000 * 0.9235 * 0.153); assert _se == 5652
# Installment sale: basis 40,000, price 100,000, 25,000 received.
_gp = 30000 * (90000 - 27000) // 90000; assert _gp == 21000
# Insolvency: debt canceled 15,000; liabilities 60,000; assets 52,000.
_inc = 15000 - min(15000, 60000 - 52000); assert _inc == 7000

